#include <domains/processes/inventory.hpp>
#include <algorithm>
#include <fstream>
#include <sstream>
namespace rebuntu::domains::process {std::optional<Process>Inventory::get(int pid)const{auto dir=proc_/std::to_string(pid);std::ifstream f(dir/"stat");std::string line;if(!std::getline(f,line))return{};auto l=line.find('('),r=line.rfind(')');if(l==std::string::npos||r==std::string::npos||r+2>=line.size())return{};Process p;p.pid=pid;p.name=line.substr(l+1,r-l-1);std::istringstream s(line.substr(r+2));std::vector<std::string>x;for(std::string v;s>>v;)x.push_back(v);if(x.size()<20)return{};p.state=x[0];try{p.ppid=std::stoi(x[1]);p.nice=std::stol(x[16]);p.start_ticks=std::stoull(x[19]);}catch(...){return{};}std::ifstream c(dir/"cmdline",std::ios::binary);std::string z((std::istreambuf_iterator<char>(c)),{});std::replace(z.begin(),z.end(),'\0',' ');if(!z.empty()&&z.back()==' ')z.pop_back();p.cmdline=z;return p;}std::vector<Process>Inventory::all()const{std::vector<Process>o;if(!std::filesystem::exists(proc_))return o;for(auto&e:std::filesystem::directory_iterator(proc_)){auto n=e.path().filename().string();if(n.empty()||!std::all_of(n.begin(),n.end(),::isdigit))continue;if(auto p=get(std::stoi(n)))o.push_back(*p);}std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.pid<b.pid;});return o;}}
